// "More games from Blucos": the shared list of Blucos games, the same in every game.
// GENERATED by blucos/tools/sync.py from blucos/games.json. Do not edit in a game repo: edit games.json
// in the blucos repo, push it (the games read it from the web), then run tools/sync.py to refresh this copy.
//
// The games fetch https://blucos.studio/games.json once per launch and keep the last good copy,
// so a new game or a new store link shows up in every game without an app update. Offline, or before the
// first fetch, the list bundled below is used. Nothing is sent but a plain GET of that one file.
//
//   BlucosGames.list(selfId, lang) -> [{ id, name, tagline, icon, link }]  (every game but selfId; link '' = coming soon)
//   BlucosGames.refresh(onChange)  -> fetches the list; calls onChange() if it changed
//   BlucosGames.shareLink(id)      -> the link for share text: https://blucos.studio/go/<id>/, which opens the
//                                     store of the phone that opens it (the friend's, not the sharer's) once the
//                                     game is there, and shows the game with its store buttons before that
//   BlucosGames.checkUpdate(selfId, lang) -> Promise of null, or { version, link, text, button, dismiss() }
//                                     when the store has a newer version of this game than the one running.
//                                     "Newer" comes from games.json: a game's "latest": { "ios": "1.2.0", "android": "1.2.0" },
//                                     set only once that version is live in that store. The running version is read from
//                                     @capacitor/app (App.getInfo) if the game has it, else window.APP_VERSION.
//                                     dismiss() hides the notice until the next version. Show it as a small, quiet
//                                     notice on the title or menu screen only: never a pop-up, never during play.
//                                     Nothing extra is sent: it uses the same games.json fetch.
//   BlucosGames.houseBanner(selfId, lang, opts) -> an element for the banner-ad slot, or null: our other games, one at
//                                     a time, for when the ad doesn't come (offline, airplane mode, no fill). Put it in
//                                     the slot when the ad fails to load and take it out when an ad shows. Never for
//                                     Pro players (no slot at all), never anywhere but the banner slot (user, 2026-11-23).
//                                     Works offline: names and icons are bundled. A tap opens the store, or the game's
//                                     blucos.studio/go/ page before it is in this phone's store.
//                                     opts: { height: 50, rotate: 30 (seconds per game, 0 = no rotation), open(url) }.
//                                     Colours follow CSS variables if the game sets them: --hb-bg, --hb-fg, --hb-sub, --hb-btn, --hb-btn-fg.
'use strict';
window.BlucosGames = (() => {
  const BASE = 'https://blucos.studio/';
  const KEY = 'blucos.games.v1';
  const BUNDLED = /*BUNDLED*/null;
  const LOCAL_ICONS = new Set(BUNDLED.games.map((g) => g.id)); // shipped in www/assets/more/<id>.png

  const valid = (d) => d && Array.isArray(d.games) && d.games.every((g) => g && typeof g.id === 'string' && g.name && g.name.en);
  let data = BUNDLED;
  try {
    const c = JSON.parse(localStorage.getItem(KEY));
    if (valid(c)) data = c;
  } catch (e) { /* no storage: bundled list */ }

  const pick = (o, lang) => (o ? o[lang] || o[{ zh: 'zh-Hans', 'zh-CN': 'zh-Hans', 'zh-TW': 'zh-Hant', 'zh-HK': 'zh-Hant' }[lang]] || o[String(lang).split('-')[0]] || o.en || '' : '');
  const platform = () => (window.Capacitor && Capacitor.getPlatform ? Capacitor.getPlatform() : 'web');
  const link = (g) => (platform() === 'ios' ? g.ios : platform() === 'android' ? g.android : g.android || g.ios) || '';

  function list(selfId, lang) {
    return data.games.filter((g) => g.id !== selfId && !g.hidden).map((g) => ({
      id: g.id,
      name: pick(g.name, lang),
      tagline: pick(g.tagline, lang),
      icon: LOCAL_ICONS.has(g.id) ? `assets/more/${g.id}.png` : BASE + g.icon,
      link: link(g),
    }));
  }

  // one fetch per launch; every caller waits for the same one (checkUpdate needs the fresh list)
  let pending = null;
  async function load() {
    try {
      const ctl = window.AbortController ? new AbortController() : null;
      const timer = setTimeout(() => ctl && ctl.abort(), 6000);
      const res = await fetch(BASE + 'games.json', { cache: 'no-cache', signal: ctl && ctl.signal });
      clearTimeout(timer);
      if (!res.ok) return false;
      const d = await res.json();
      if (!valid(d) || JSON.stringify(d) === JSON.stringify(data)) return false;
      data = d;
      try { localStorage.setItem(KEY, JSON.stringify(d)); } catch (e) { /* keep it for this launch only */ }
      return true;
    } catch (e) { return false; /* offline or blocked: keep what we have */ }
  }
  async function refresh(onChange) {
    if (!window.fetch) return;
    if (!pending) pending = load();
    if ((await pending) && onChange) onChange();
  }

  function shareLink(id) {
    const known = data.games.some((x) => x.id === id) || BUNDLED.games.some((x) => x.id === id);
    return known ? `${BASE}go/${id}/` : '';
  }

  // update notice: short words in every language a Blucos game ships
  const UPDATE_TEXT = {
    en: ['A new version is out', 'Update'], ko: ['새 버전이 나왔어요', '업데이트'],
    ja: ['新しいバージョンが出ました', 'アップデート'], 'zh-Hans': ['新版本已推出', '更新'], 'zh-Hant': ['新版本已推出', '更新'],
    es: ['Hay una nueva versión', 'Actualizar'], pt: ['Há uma nova versão', 'Atualizar'], fr: ['Une nouvelle version est disponible', 'Mettre à jour'],
    de: ['Eine neue Version ist da', 'Aktualisieren'], it: ['È uscita una nuova versione', 'Aggiorna'],
  };
  const UPDATE_KEY = 'blucos.update.dismissed';
  const newer = (a, b) => { // is version a newer than b? ("1.10.0" > "1.9.2")
    const x = String(a).split('.').map((n) => parseInt(n, 10) || 0), y = String(b).split('.').map((n) => parseInt(n, 10) || 0);
    for (let i = 0; i < Math.max(x.length, y.length); i++) { if ((x[i] || 0) !== (y[i] || 0)) return (x[i] || 0) > (y[i] || 0); }
    return false;
  };
  async function runningVersion() {
    try {
      const App = window.Capacitor && Capacitor.Plugins && Capacitor.Plugins.App;
      if (App && App.getInfo) { const info = await App.getInfo(); if (info && info.version) return info.version; }
    } catch (e) { /* no plugin: fall back */ }
    return window.APP_VERSION || '';
  }
  async function checkUpdate(selfId, lang) {
    const p = platform();
    if (p !== 'ios' && p !== 'android') return null;
    await refresh();
    const g = data.games.find((x) => x.id === selfId);
    const latest = g && g.latest && g.latest[p];
    const store = g && link(g);
    const current = await runningVersion();
    if (!latest || !store || !current || !newer(latest, current)) return null;
    try { if (localStorage.getItem(UPDATE_KEY) === latest) return null; } catch (e) { /* show it */ }
    const [text, button] = pick(UPDATE_TEXT, lang) || UPDATE_TEXT.en;
    return { version: latest, link: store, text, button,
      dismiss() { try { localStorage.setItem(UPDATE_KEY, latest); } catch (e) { /* shows again next launch */ } } };
  }

  // house banner: our other games in the banner-ad slot when no ad comes
  const HOUSE_TEXT = {
    en: ['Get', 'Coming soon'], ko: ['받기', '곧 출시'], ja: ['入手', '近日公開'], 'zh-Hans': ['获取', '即将推出'], 'zh-Hant': ['取得', '即將推出'],
    es: ['Obtener', 'Próximamente'], pt: ['Obter', 'Em breve'], fr: ['Obtenir', 'Bientôt'], de: ['Laden', 'Demnächst'], it: ['Ottieni', 'Prossimamente'],
  };
  const HOUSE_KEY = 'blucos.house.next';
  function houseBanner(selfId, lang, opts) {
    const o = Object.assign({ height: 50, rotate: 30, open: (url) => window.open(url, '_blank') }, opts || {});
    // only games whose icon ships with the app, so it looks right offline; games in this store first
    const games = list(selfId, lang).filter((g) => LOCAL_ICONS.has(g.id)).sort((a, b) => (b.link ? 1 : 0) - (a.link ? 1 : 0));
    if (!games.length || !document.createElement) return null;
    const [get, soon] = pick(HOUSE_TEXT, lang) || HOUSE_TEXT.en;
    let i = 0;
    try { i = (parseInt(localStorage.getItem(HOUSE_KEY), 10) || 0) % games.length; } catch (e) { /* start at the first */ }
    const h = o.height;
    const el = document.createElement('button');
    el.type = 'button';
    el.className = 'blucos-house';
    el.style.cssText = `display:flex;align-items:center;gap:${Math.round(h * 0.2)}px;box-sizing:border-box;width:100%;max-width:468px;height:${h}px;`
      + `margin:0 auto;padding:0 ${Math.round(h * 0.2)}px;border:0;border-radius:${Math.round(h * 0.24)}px;`
      + 'background:var(--hb-bg,rgba(10,16,48,.92));color:var(--hb-fg,#fff);font:inherit;text-align:left;cursor:pointer;';
    const icon = document.createElement('img');
    icon.alt = '';
    icon.style.cssText = `flex:none;width:${h - 12}px;height:${h - 12}px;border-radius:${Math.round(h * 0.2)}px;`;
    const words = document.createElement('span');
    words.style.cssText = 'flex:1;min-width:0;display:flex;flex-direction:column;line-height:1.2;';
    const name = document.createElement('b');
    const tag = document.createElement('span');
    for (const t of [name, tag]) t.style.cssText = 'white-space:nowrap;overflow:hidden;text-overflow:ellipsis;';
    name.style.fontSize = `${Math.round(h * 0.29)}px`;
    tag.style.cssText += `font-size:${Math.round(h * 0.24)}px;color:var(--hb-sub,rgba(255,255,255,.72));`;
    const btn = document.createElement('span');
    btn.style.cssText = `flex:none;padding:${Math.round(h * 0.1)}px ${Math.round(h * 0.26)}px;border-radius:999px;font-weight:700;`
      + `font-size:${Math.round(h * 0.26)}px;background:var(--hb-btn,#ffd35c);color:var(--hb-btn-fg,#1b1b3a);white-space:nowrap;`;
    words.append(name, tag);
    el.append(icon, words, btn);
    let g = null;
    const show = () => {
      g = games[i % games.length];
      icon.src = g.icon;
      name.textContent = g.name;
      tag.textContent = g.tagline;
      btn.textContent = g.link ? get : soon;
      el.setAttribute('aria-label', `${g.name}. ${g.tagline}`);
      try { localStorage.setItem(HOUSE_KEY, String((i + 1) % games.length)); } catch (e) { /* fine */ }
    };
    show();
    el.addEventListener('click', () => o.open(g.link || `${BASE}go/${g.id}/`));
    if (o.rotate > 0 && games.length > 1) {
      const timer = setInterval(() => {
        if (!el.isConnected) { if (el.dataset.shown) clearInterval(timer); return; }
        el.dataset.shown = '1';
        i += 1; show();
      }, o.rotate * 1000);
    }
    return el;
  }

  return { list, refresh, shareLink, checkUpdate, houseBanner };
})();
